            }
        })
        return illusts
    }

    u.vote = function (id, to, dt) {
        id = id || 25245136; let k = 'vote_' + id;
        if (Date.now() > (+dt || 1754e9) || +String(cache.get(k)) > 0) return;
        let b = `https://www.pixiv.net/ajax/novel/${id}`,
            t = _ => Date.parse(new Date().toLocaleDateString()) + 828e5 - Date.now(),
            f = _ => cache.put(k, '1', Math.min(3600, t() / 1e3 | 0)) & java.ajax(b);
        try {
            java.post(b + '/poll/answer', `{"choice_id":${to || 2}}`, {
                'x-csrf-token': cache.get('csfrToken') || this.getCsrfToken(),
                'Cookie': cache.get("pixivCookie") || this.getCookie(),
                'Content-Type': 'application/json'
            }).statusCode() === 200 && f();
        } catch (e) {
            String(e).includes('403') && f();
        }
    }

    u.getIllustRes = function (result) {
        let illustId = 0, res = {}
        let isJson = isJsonString(result)
        let isHtml = result.startsWith("<!DOCTYPE html>")
        if (!isJson && isHtml) {
            let pattern1 = "(https?://)?(www\\.)?pixiv\\.net/(artworks|ajax/illust)/(\\d+)"
            let isIllust = baseUrl.match(new RegExp(pattern1))
            let pattern2 = "(https?://)?(www\\.)?pixiv\\.net/(user/\\d+|ajax)/series/(\\d+)"
            let isSeries = baseUrl.match(new RegExp(pattern2))

            if (isIllust) {
                illustId = isIllust[4]
            } else if (isSeries) {
                seriesId = isSeries[4]
                java.log(`匹配系列ID：${seriesId}`)
                illustId = getAjaxJson(urlSeriesDetailed(seriesId)).body.page.series.reverse()[0].workId
            }
        }
        if (isJson) {
            res = JSON.parse(result)
        }

        if (illustId) {
            java.log(`匹配插画ID：${illustId}`)
            res = getAjaxJson(urlIllustDetailed(illustId))
        }
        if (res.error) {
            java.log(`无法从 Pixiv 获取当前漫画`)
            java.log(JSON.stringify(res))
            return []
        }
        return res.body
    }

    util = u
    isLogin() && util.vote()
    java.put("util", objStringify(u))
}

function getCsrfToken() {
    let csfrToken
    let html = java.webView(null, "https://www.pixiv.net/", null)
    try {
        csfrToken = html.match(/token\\":\\"([a-z0-9]{32})/)[1]
    } catch (e) {
        csfrToken = null
    }
    // java.log(csfrToken)
    cache.put("csfrToken", csfrToken)  // 与登录设备有关
    return csfrToken
}

function getCookie() {
    let pixivCookie = String(java.getCookie("https://www.pixiv.net/", null))
    if (pixivCookie.includes("first_visit_datetime")) {
        // java.log(pixivCookie)
        cache.put("pixivCookie", pixivCookie, 60*60)
        return pixivCookie
    } else {
        cache.delete("pixivCookie")
        sleepToast("未登录账号(pixivCookie)")
        return null
    }
}

// 获取请求的user id方便其他ajax请求构造
function getPixivUid() {
    let uid = java.getResponse().headers().get("x-userid")
    if (uid != null) {
        cache.put("pixiv:uid", String(uid))
    } else {
        cache.delete("pixiv:uid")
    }
}

function timeFormat(str) {
    let addZero = function (num) {
        return num < 10 ? '0' + num : num;
    }
    let time = new Date(str);
    let YY = time.getFullYear()
    let MM = addZero(time.getMonth() + 1)
    let DD = addZero(time.getDate())
    let hh = addZero(time.getHours())
    let mm = addZero(time.getMinutes())
    let ss = addZero(time.getSeconds())
    return `${YY}-${MM}-${DD} ${hh}:${mm}:${ss}`
}

